export function validateThresholds({ thresholds = {}, evaluations }) {
  const metricIds = new Set(evaluations.map(m => m.id));
  const errors = [];

  for (const [metricId, minValue] of Object.entries(thresholds)) {
    if (!metricIds.has(metricId)) {
      const validIds = Array.from(metricIds).sort();
      errors.push(`Unknown metric: "${metricId}". Valid metrics are: ${validIds.join(', ')}`);
    } else if (typeof minValue !== 'number' || minValue < 0 || minValue > 1) {
      errors.push(`Invalid threshold for "${metricId}": minimum must be a number between 0 and 1, got ${minValue}`);
    }
  }

  return errors;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds = {},
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdsList = [];
  let allPassed = true;

  for (const [metricId, min] of Object.entries(thresholds)) {
    const metric = evaluations.find(m => m.id === metricId);
    const score = metric?.score;
    const passed = score !== null && score !== undefined && score >= min;

    if (!passed) allPassed = false;

    thresholdsList.push({
      metric: metricId,
      min,
      score: score ?? null,
      passed
    });
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (Object.keys(thresholds).length > 0) {
    report.passed = allPassed;
    report.thresholds = thresholdsList;
  }

  return report;
}

