function parseThresholds(thresholdStrings: string | string[] | undefined): Record<string, number> {
  const thresholds: Record<string, number> = {};

  if (!thresholdStrings) {
    return thresholds;
  }

  const strings = Array.isArray(thresholdStrings) ? thresholdStrings : [thresholdStrings];

  for (const str of strings) {
    const match = str.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(`Malformed threshold: "${str}". Expected format: <metric>=<number> (e.g., exact_match=0.9)`);
    }

    const metricId = match[1];
    const minValue = parseFloat(match[2]);

    if (isNaN(minValue) || minValue < 0 || minValue > 1) {
      throw new Error(`Invalid threshold minimum for "${metricId}": must be a number between 0 and 1, got ${match[2]}`);
    }

    thresholds[metricId] = minValue;
  }

  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let thresholds: Record<string, number> = {};
  try {
    thresholds = parseThresholds(options.threshold);
  } catch (error) {
    log.error((error as Error).message);
    process.exit(2);
  }

  const validateThresholds = (Eval.validateThresholds as unknown as (config: unknown) => string[]) | undefined;
  if (validateThresholds && thresholds && Object.keys(thresholds).length > 0) {
    const errors = validateThresholds({
      thresholds,
      evaluations
    });
    if (errors.length > 0) {
      log.error('Threshold validation failed:');
      errors.forEach((err) => console.error(`  - ${err}`));
      process.exit(2);
    }
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (thresholds && Object.keys(thresholds).length > 0) {
    const passed = report.passed;
    if (!passed) {
      const failedThresholds = report.thresholds.filter((t: any) => !t.passed);
      log.error('Thresholds failed:');
      failedThresholds.forEach((t: any) => {
        const score = t.score !== null ? t.score : 'n/a';
        console.error(`  - ${t.metric}: score ${score}, minimum ${t.min}`);
      });
      process.exit(1);
    }
  }
}

