477	function parseThresholds(thresholdStrings: string | string[] | undefined): Record<string, number> {
478	  const thresholds: Record<string, number> = {};
479	
480	  if (!thresholdStrings) {
481	    return thresholds;
482	  }
483	
484	  const strings = Array.isArray(thresholdStrings) ? thresholdStrings : [thresholdStrings];
485	
486	  for (const str of strings) {
487	    const match = str.match(/^([a-z_]+)=([0-9.]+)$/);
488	    if (!match) {
489	      throw new Error(`Malformed threshold: "${str}". Expected format: <metric>=<number> (e.g., exact_match=0.9)`);
490	    }
491	
492	    const metricId = match[1];
493	    const minValue = parseFloat(match[2]);
